use serde_json::{json,Value};
use sha2::{Digest,Sha256};
use std::{collections::BTreeMap,fs,io::Read,path::Path};
fn hash(p:&Path)->String{let mut f=fs::File::open(p).unwrap();let mut h=Sha256::new();let mut b=[0;65536];loop{let n=f.read(&mut b).unwrap();if n==0{break;}h.update(&b[..n]);}format!("{:x}",h.finalize())}
fn copy_file(src:&Path,dst:&Path,index:&mut BTreeMap<String,String>,root:&Path){assert!(src.symlink_metadata().unwrap().file_type().is_file());fs::create_dir_all(dst.parent().unwrap()).unwrap();fs::copy(src,dst).unwrap();let digest=hash(src);assert_eq!(hash(dst),digest);index.insert(dst.strip_prefix(root).unwrap().to_str().unwrap().into(),digest);}
fn tree(src:&Path,dst:&Path,index:&mut BTreeMap<String,String>,root:&Path){let mut entries=fs::read_dir(src).unwrap().map(|e|e.unwrap().path()).collect::<Vec<_>>();entries.sort();for p in entries{let name=p.file_name().unwrap();let d=dst.join(name);if p.is_dir(){tree(&p,&d,index,root)}else{let n=name.to_str().unwrap();if ["candidate-sdk","zopro-candidate","zopro-accepted","zopro-xtask","review","serve-results"].contains(&n){continue;}copy_file(&p,&d,index,root);}}}
fn main(){let src=Path::new("/tmp/zopro-bounded-steal-search/aws");let report=Path::new("/home/ubuntu/src/zk-tools/zopro/docs/benchmarks/2026-10-26-bounded-steal-search-c7a");let dst=report.join("artifacts");assert!(!dst.exists());let mut index=BTreeMap::new();for name in ["archive-sha256.txt","bench-request.json","bench-remote.sh","bench-result.json","context-pins.json","image-manifest.json","local-output-permission-probe.txt","local-output-permission-repair.json","local-output-permissions-after.txt","local-output-permissions-before.txt","local-preflight-permission-error.log","local-preflight.log","local-verify-pins.json","local-verify-plan.json","local-verify.log","make-context.rs","make-context.log","make-local-verify.rs","pack-remote.sh","pack-result.json","parent-input-pins.json","parent-input-sha256.txt","pre-launch-protocol-sha256.txt","prepare-request.json","prepare-result.json","resource-review.rs","resource-review-result.json","resource-review-source.sha256","review.rs","review-tests.log","serve.rs","closeout.rs","closeout.json","cleanup-complete.json","ecr-tag-final.json","volumes-final.json","instance-final.json","restart-transfer-request.json","restart-transfer-result.json","publish.rs"]{copy_file(&src.join(name),&dst.join(name),&mut index,&dst);}
for name in ["context","local-output","local-review","local-verify","remote-results"]{tree(&src.join(name),&dst.join(name),&mut index,&dst);}
let parent=src.parent().unwrap();for name in ["server-build-plan.json","server-build.log"]{copy_file(&parent.join(name),&dst.join(name),&mut index,&dst);}tree(&parent.join("server-build"),&dst.join("server-build"),&mut index,&dst);
let mut proof_members=0;let inventory:Value=serde_json::from_slice(&fs::read(src.join("local-review/proof-inventory.json")).unwrap()).unwrap();for(name,expected)in inventory.as_object().unwrap(){let name=format!("remote-results/output/{name}");assert_eq!(index[&name],expected.as_str().unwrap());proof_members+=1;}assert_eq!(proof_members,302);
let raw=index.keys().filter(|p|p.ends_with("/perf.data")).count();let symbols=index.keys().filter(|p|p.ends_with("/symbols/stdout.log")).count();assert_eq!(raw,18);assert_eq!(symbols,18);
let sums=index.iter().map(|(p,h)|format!("{h}  {p}\n")).collect::<String>();fs::write(dst.join("SHA256SUMS"),sums).unwrap();fs::write(dst.join("artifact-index.json"),format!("{}\n",serde_json::to_string_pretty(&json!({"files":index.len(),"proof_public_members":proof_members,"raw_perf":raw,"expanded_symbols":symbols,"sha256":index,"scope":"C7a target stage archival copies;18raw captures and18expanded streams kept locally and ignored from Git. Executables/cache/private infra payloads excluded; source/build/link/image identities retained."})).unwrap())).unwrap();fs::write(report.join(".gitignore"),"/artifacts/**/perf.data\n/artifacts/**/symbols/stdout.log\n").unwrap();println!("ARCHIVE_VERIFIED {} files,302 remote proof/public members,18 raw captures/18 expanded streams",index.len());}
